function createRecipeBook(notify) {
  if (typeof notify !== 'function') throw new TypeError('notify must be a function');
  const records = new Map();

  const copy = (record) => ({
    key: record.key,
    title: record.title,
    ingredients: record.ingredients.slice()
  });

  const validateKey = (key) => {
    if (typeof key !== 'string' || key.trim() === '') throw new TypeError('invalid key');
  };

  const validateRecord = (record) => {
    if (!record || typeof record !== 'object' || Array.isArray(record)) throw new TypeError('invalid record');
    validateKey(record.key);
    if (typeof record.title !== 'string' || record.title.trim() === '') throw new TypeError('invalid title');
    if (!Array.isArray(record.ingredients) ||
        record.ingredients.some((value) => typeof value !== 'string' || value.trim() === '')) {
      throw new TypeError('invalid ingredients');
    }
  };

  async function run(operation, action) {
    notify({ operation, phase: 'start' });
    let result;
    try {
      result = await action();
    } catch (error) {
      notify({ operation, phase: 'failure', error });
      throw error;
    }
    notify({ operation, phase: 'success' });
    return result;
  }

  return {
    async add(record) {
      return run('add', async () => {
        validateRecord(record);
        if (records.has(record.key)) throw new Error('duplicate key');
        const stored = copy(record);
        records.set(stored.key, stored);
        return copy(stored);
      });
    },
    async get(key) {
      return run('get', async () => {
        validateKey(key);
        const record = records.get(key);
        return record ? copy(record) : null;
      });
    },
    async update(key, changes) {
      return run('update', async () => {
        validateKey(key);
        if (!changes || typeof changes !== 'object' || Array.isArray(changes) ||
            (!Object.prototype.hasOwnProperty.call(changes, 'title') &&
             !Object.prototype.hasOwnProperty.call(changes, 'ingredients'))) {
          throw new TypeError('invalid changes');
        }
        const current = records.get(key);
        if (!current) throw new Error('missing key');
        const next = {
          key,
          title: Object.prototype.hasOwnProperty.call(changes, 'title') ? changes.title : current.title,
          ingredients: Object.prototype.hasOwnProperty.call(changes, 'ingredients') ? changes.ingredients : current.ingredients
        };
        validateRecord(next);
        const stored = copy(next);
        records.set(key, stored);
        return copy(stored);
      });
    },
    async remove(key) {
      return run('remove', async () => {
        validateKey(key);
        return records.has(key);
      });
    }
  };
}

