'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api), ['createRecipeBook']);
const { createRecipeBook } = api;
assert.throws(() => createRecipeBook(), TypeError);
assert.throws(() => createRecipeBook({}), TypeError);

(async () => {
  const notices = [];
  const book = createRecipeBook(message => { notices.push(message); return 'ignored'; });
  assert.deepEqual(Object.keys(book).sort(), ['add', 'get', 'remove', 'update']);
  for (const name of Object.keys(book)) {
    assert.equal(book[name].constructor.name, 'AsyncFunction');
  }

  const source = { key: 'r1', title: '  Soup  ', ingredients: ['water', ' salt '] };
  const added = await book.add(source);
  assert.deepEqual(added, source);
  assert.notStrictEqual(added, source);
  assert.notStrictEqual(added.ingredients, source.ingredients);
  source.title = 'changed';
  source.ingredients[0] = 'changed';
  added.title = 'also changed';
  added.ingredients.push('pepper');
  assert.deepEqual(await book.get('r1'), {
    key: 'r1', title: '  Soup  ', ingredients: ['water', ' salt ']
  });

  const getA = await book.get('r1');
  const getB = await book.get('r1');
  assert.notStrictEqual(getA, getB);
  assert.notStrictEqual(getA.ingredients, getB.ingredients);
  assert.equal(await book.get('absent'), null);

  const changes = { title: 'Stew', ingredients: ['potato'] };
  const updated = await book.update('r1', changes);
  assert.deepEqual(updated, { key: 'r1', title: 'Stew', ingredients: ['potato'] });
  assert.notStrictEqual(updated.ingredients, changes.ingredients);
  changes.title = 'mutated';
  changes.ingredients[0] = 'mutated';
  updated.ingredients[0] = 'returned mutation';
  assert.deepEqual(await book.get('r1'), { key: 'r1', title: 'Stew', ingredients: ['potato'] });

  assert.equal(await book.remove('missing'), false);
  assert.equal(await book.remove('r1'), true);
  assert.equal(await book.get('r1'), null);

  for (const record of [null, {}, { key: '', title: 'x', ingredients: [] },
    { key: 'x', title: '   ', ingredients: [] },
    { key: 'x', title: 'ok', ingredients: 'x' },
    { key: 'x', title: 'ok', ingredients: [''] },
    { key: 'x', title: 'ok', ingredients: [2] }]) {
    await assert.rejects(book.add(record), TypeError);
  }

  await book.add({ key: 'dup', title: 'Valid', ingredients: [] });
  await assert.rejects(book.add({ key: 'dup', title: 'Other', ingredients: [] }), Error);
  await assert.rejects(book.get(''), TypeError);
  await assert.rejects(book.remove(null), TypeError);
  await assert.rejects(book.update('absent', { title: 'x' }), Error);
  await assert.rejects(book.update('dup', {}), TypeError);
  await assert.rejects(book.update('dup', { title: ' ' }), TypeError);
  await assert.rejects(book.update('dup', { ingredients: [''] }), TypeError);
  assert.deepEqual(await book.get('dup'), { key: 'dup', title: 'Valid', ingredients: [] });

  assert.deepEqual(notices[0], { operation: 'add', phase: 'start' });
  assert.deepEqual(notices[1], { operation: 'add', phase: 'success' });
  const failureNotice = notices.find(n => n.operation === 'add' && n.phase === 'failure');
  assert.ok(failureNotice);
  assert.ok(failureNotice.error instanceof Error);

  const notificationError = new Error('notify stopped');
  let notifyCalls = 0;
  const blocked = createRecipeBook(() => { notifyCalls += 1; throw notificationError; });
  await assert.rejects(
    blocked.add({ key: 'x', title: 'X', ingredients: [] }),
    error => error === notificationError
  );
  assert.equal(notifyCalls, 1);
})().catch(error => { console.error(error); process.exitCode = 1; });

